import { Component, computed, input } from '@angular/core';
import { HrmAvatar } from './hrm-avatar';

/** 1 thành viên trong nhóm avatar. text = chữ viết tắt (bỏ trống → tự suy từ name). */
export interface HrmAvatarGroupItem {
  src?: string;
  name: string;
  text?: string;
}

/** hrm-avatar-group — xếp chồng mép nhiều avatar thành một hàng (người tham gia dự án,
 *  chuỗi người duyệt). Quá `max` → gộp thành avatar "+N". colorful mặc định bật
 *  (màu theo tên, đồng bộ hrm-avatar). compact = nhỏ + chồng sát hơn cho bảng dày. */
@Component({
  selector: 'hrm-avatar-group',
  imports: [HrmAvatar],
  template: `
    @for (it of visible(); track $index) {
      <hrm-avatar
        class="ag-item"
        [src]="it.src || ''"
        [text]="it.text || initials(it.name)"
        [colorful]="colorful()"
        [colorSeed]="it.name"
        [size]="avatarSize()"
        [shape]="shape()" />
    }
    @if (overflow() > 0) {
      <hrm-avatar class="ag-item ag-more" [text]="'+' + overflow()" [size]="avatarSize()" [shape]="shape()" />
    }
  `,
  host: { class: 'hrm-avatar-group', '[class.hrm-avatar-group--compact]': 'compact()' },
  styles: [`
:host { display: inline-flex; align-items: center; }
.ag-item + .ag-item { margin-left: -10px; }
:host(.hrm-avatar-group--compact) .ag-item + .ag-item { margin-left: -8px; }
/* Vòng viền màu nền quanh mỗi avatar để tách lớp khi chồng mép. */
.ag-item ::ng-deep .ant-avatar { box-shadow: 0 0 0 2px var(--bg-surface); }
.ag-more ::ng-deep .ant-avatar { background: var(--bg-surface-subtle); color: var(--text-sub); }
  `],
})
export class HrmAvatarGroup {
  readonly items = input<HrmAvatarGroupItem[]>([]);
  /** Số avatar tối đa hiện trước khi gộp "+N". */
  readonly max = input(4);
  readonly size = input<number | 'small' | 'default' | 'large'>(32);
  readonly shape = input<'circle' | 'square'>('circle');
  readonly colorful = input(true);
  /** Nhỏ + chồng sát hơn — cho bảng dày. */
  readonly compact = input(false);

  protected readonly visible = computed(() => this.items().slice(0, this.max()));
  protected readonly overflow = computed(() => Math.max(0, this.items().length - this.max()));
  /** compact: size số tự giảm còn 24 nếu caller không đổi mặc định. */
  protected readonly avatarSize = computed(() => {
    const s = this.size();
    return this.compact() && s === 32 ? 24 : s;
  });

  protected initials(name: string): string {
    const n = (name || '').trim();
    if (!n) return '';
    const parts = n.split(/\s+/);
    const first = parts[0][0] ?? '';
    const last = parts.length > 1 ? parts[parts.length - 1][0] : '';
    return (first + last).toUpperCase();
  }
}
